<div id="page-content" class="page-wrapper clearfix"><div class="card"><div class="page-title clearfix"><h1><?php echo app_lang('engenharia_checklists'); ?></h1><div class="title-button-group"><?php echo modal_anchor(get_uri('engenharia/checklists/modal_form'), "<i data-feather='plus-circle' class='icon-16'></i> " . app_lang('engenharia_add_checklist'), array('class'=>'btn btn-primary')); ?></div></div><?php echo modal_anchor(get_uri('engenharia/checklists/modal_form'), "<i data-feather='plus-circle' class='icon-16'></i> " . app_lang('engenharia_add_checklist'), array('class'=>'btn btn-primary w-100 d-md-none mb15')); ?><div class="table-responsive"><table class="table table-hover"><thead><tr><th><?php echo app_lang('name'); ?></th><th><?php echo app_lang('code'); ?></th><th><?php echo app_lang('engenharia_type'); ?></th><th><?php echo app_lang('engenharia_version'); ?></th><th><?php echo app_lang('status'); ?></th><th class="text-center"><?php echo app_lang('actions'); ?></th></tr></thead><tbody><?php if ($checklists) { foreach($checklists as $row) { ?><tr><td><a class="strong" href="<?php echo get_uri('engenharia/checklists/manage/' . $row->id); ?>"><?php echo esc($row->name); ?></a><br><small class="text-muted"><?php echo esc($row->description); ?></small></td><td><?php echo esc($row->code); ?></td><td><?php echo esc($row->type_name ?: '-'); ?></td><td><?php echo (int)$row->version; ?></td><td><?php echo !empty($row->is_enabled) ? '<span class="badge bg-success">' . app_lang('engenharia_active') . '</span>' : '<span class="badge bg-secondary">' . app_lang('engenharia_inactive') . '</span>'; ?></td><td class="text-center"><div class="btn-group"><a class="btn btn-default btn-sm" href="<?php echo get_uri('engenharia/checklists/manage/' . $row->id); ?>" title="<?php echo app_lang('edit'); ?>"><i data-feather="edit" class="icon-14"></i></a><a class="btn btn-default btn-sm" href="<?php echo get_uri('engenharia/checklists/preview/' . $row->id); ?>" title="<?php echo app_lang('view'); ?>"><i data-feather="eye" class="icon-14"></i></a><button class="btn btn-default btn-sm engenharia-checklist-duplicate" data-id="<?php echo $row->id; ?>" title="<?php echo app_lang('duplicate'); ?>"><i data-feather="copy" class="icon-14"></i></button><button class="btn btn-default btn-sm engenharia-checklist-toggle" data-id="<?php echo $row->id; ?>" data-enabled="<?php echo !empty($row->is_enabled) ? 0 : 1; ?>" title="<?php echo app_lang('engenharia_toggle'); ?>"><i data-feather="power" class="icon-14"></i></button></div></td></tr><?php } } else { ?><tr><td colspan="6" class="text-muted"><?php echo app_lang('engenharia_no_checklists'); ?></td></tr><?php } ?></tbody></table></div></div></div>
<script>$(function(){ $('.engenharia-checklist-duplicate').on('click',function(){if(!confirm('<?php echo app_lang('engenharia_confirm_duplicate'); ?>'))return;$.post('<?php echo_uri('engenharia/checklists/duplicate'); ?>',{id:$(this).data('id')},function(r){if(r.success)location.reload();else appAlert.error(r.message);},'json');});$('.engenharia-checklist-toggle').on('click',function(){var b=$(this);$.post('<?php echo_uri('engenharia/checklists/toggle'); ?>',{id:b.data('id'),enabled:b.data('enabled')},function(r){if(r.success)location.reload();else appAlert.error(r.message);},'json');});});</script>
